// THE SCORE: every time comes from the dialogue (vo.js, generated by narration.py), so shots,
// lip-sync, captions, signs and sounds share one clock. Name moments after LINES ids and phrases.
(function () {
  const node = typeof require !== 'undefined';
  const U = node ? require('./engine/util') : globalThis.U;
  const MU = node ? require('./engine/music') : globalThis.MUSIC;
  const VO = node ? require('./vo') : globalThis.VO;
  const { m, makeClock, makeChords } = MU;

  const FPS = 30;
  const FORMAT = U.pickFormat('16:9'); // render.js --format 9:16 gives the phone version of the same film
  const [W, H] = U.formatSize(FORMAT);
  const SAFE = U.safeArea(W, H);
  const clock = makeClock({ bpm: 96, offset: 0 });
  const { T, BEAT } = clock;

  const L = {};
  for (const l of VO.lines) L[l.id] = l;
  const ph = (id, k) => L[id].phrases[k][1];   // start of phrase k of a line
  const sent = (id, k) => L[id].sents[k][1];   // start of sentence k of a line

  const ev = {
    hook: L.hook.t,
    middle: L.idea.t + 0.2, halve: sent('idea', 1) + 0.6,
    wow: L.wow.t,
    count: L.count.t, n500: ph('count', 2), n250: ph('count', 3), ten: ph('count', 4),
  };
  const SPEECH_END = VO.lines[VO.lines.length - 1].end;
  ev.outro = SPEECH_END + 0.8;
  const DURATION = Math.ceil(SPEECH_END + 5);
  const cuts = { board: 0, outro: ev.outro };

  const { chords } = makeChords(clock, {
    Cmaj9: { notes: ['E3', 'G3', 'B3', 'D4'], bass: 'C2' }, Am7: { notes: ['G3', 'C4', 'E4'], bass: 'A1' },
    Fmaj7: { notes: ['A3', 'C4', 'E4'], bass: 'F1' }, G6: { notes: ['G3', 'B3', 'E4'], bass: 'G1' },
  }, Array.from({ length: Math.ceil(DURATION / 2.5 / 4) * 4 + 4 }, (_, i) => [i, 0, 4, ['Cmaj9', 'Am7', 'Fmaj7', 'G6'][Math.floor(i / 2) % 4]]));

  const markers = { hook: ev.hook, middle: ev.middle, halve: ev.halve, count: ev.count, outro: ev.outro };
  const SCORE = { FPS, FORMAT, W, H, SAFE, DURATION, clock, T, BEAT, m, chords, ev, cuts, markers, VO, L };
  if (node) module.exports = SCORE; else globalThis.SCORE = SCORE;
})();
